-- ----- 20261009000200_rpc.sql -----
-- Contest Scoreboard: RPC functions.
-- Error convention: raise exception 'code: human message'. The web app maps on the code.
-- Every RPC is security definer with an explicit search_path and its own permission checks.
-- Execute grants are set in 20261009000300_security.sql (default: nobody).

-- ---------------------------------------------------------------------------------------------
-- Internal helpers
-- ---------------------------------------------------------------------------------------------
create function _require_admin() returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not is_admin() then
    raise exception 'forbidden: Admins only.' using errcode = '42501';
  end if;
end $$;

create function _require_owner() returns void
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not is_owner() then
    raise exception 'forbidden: Owner only.' using errcode = '42501';
  end if;
end $$;

create function _require_reason(p_reason text) returns text
language plpgsql immutable as $$
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'reason_required: A reason is required.';
  end if;
  return btrim(p_reason);
end $$;

-- Standings for one contest. Internal; exposed through get_leaderboard / get_admin_leaderboard.
-- rank: only active members with points > 0 are ranked (points desc, earliest reached_at first).
-- ord:  display order = ranked, then active zero-point (alphabetical), then inactive.
create function _standings(p_contest uuid)
returns table (member_id uuid, email citext, display_name text, active boolean, points int,
               tasks_completed int, reached_at timestamptz, pending_count int, rank int, ord int,
               category_counts jsonb)
language sql stable security definer set search_path = public, pg_temp as $$
  with agg as (
    select m.id, m.email, m.display_name, m.active,
           coalesce(sum(s.points_awarded) filter (where s.status = 'approved'), 0)::int as pts,
           (count(*) filter (where s.status = 'approved'))::int as tasks,
           max(s.submitted_at) filter (where s.status = 'approved') as reached,
           (count(*) filter (where s.status = 'pending'))::int as pend
    from members m
    left join submissions s on s.member_id = m.id
    where m.contest_id = p_contest
    group by m.id
  ),
  category_totals as (
    select m.id as member_id, c.id as category_id, c.sort_order,
           count(s.id)::int as task_count
    from members m
    join categories c on c.contest_id = p_contest and c.active
    left join submissions s
      on s.contest_id = p_contest
     and s.member_id = m.id
     and s.category_id = c.id
     and s.status = 'approved'
    where m.contest_id = p_contest
    group by m.id, c.id, c.sort_order
  ),
  category_counts as (
    select member_id,
           jsonb_object_agg(category_id::text, task_count order by sort_order) as counts
    from category_totals
    group by member_id
  )
  select a.id, a.email, a.display_name, a.active, a.pts, a.tasks, a.reached, a.pend,
         case when a.active and a.pts > 0 then
           (row_number() over (partition by (a.active and a.pts > 0)
                               order by a.pts desc, a.reached asc nulls last, lower(a.display_name)))::int
         end,
         (row_number() over (order by a.active desc, (a.pts > 0) desc, a.pts desc,
                             a.reached asc nulls last, lower(a.display_name)))::int,
         coalesce(cc.counts, '{}'::jsonb)
  from agg a
  left join category_counts cc on cc.member_id = a.id
$$;

-- Resubmission rules, shared by draft creation and the allowance check.
-- Returns null when allowed, otherwise an error code.
create function _resubmission_block(p_parent uuid, p_member uuid) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_p submissions;
begin
  select * into v_p from submissions where id = p_parent and member_id = p_member;
  if not found then return 'bad_resubmission'; end if;
  if v_p.status not in ('rejected', 'reversed') then return 'not_resubmittable'; end if;
  if v_p.attempt >= 2 and not v_p.override_granted then return 'resubmission_limit'; end if;
  if exists (select 1 from submissions c
             where c.resubmission_of = p_parent and c.status not in ('withdrawn', 'draft')) then
    return 'resubmission_exists';
  end if;
  return null;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Shared (member or admin)
-- ---------------------------------------------------------------------------------------------
create function get_leaderboard()
returns table (display_name text, points int, tasks_completed int, rank int, reached_at timestamptz, is_me boolean,
               category_counts jsonb)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not (is_member() or is_admin()) then
    raise exception 'forbidden: Login required.' using errcode = '42501';
  end if;
  return query
    select st.display_name, st.points, st.tasks_completed, st.rank, st.reached_at,
           (st.member_id = auth.uid()), st.category_counts
    from _standings(current_contest_id()) st
    where st.active
    order by st.ord;
end $$;

create function get_admin_leaderboard()
returns table (member_id uuid, email citext, display_name text, points int, tasks_completed int,
               rank int, reached_at timestamptz, pending_count int, active boolean)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  perform _require_admin();
  return query
    select st.member_id, st.email, st.display_name, st.points, st.tasks_completed, st.rank,
           st.reached_at, st.pending_count, st.active
    from _standings(current_contest_id()) st
    order by st.ord;
end $$;

create function get_contest_banner()
returns table (contest_id uuid, name text, status contest_status, start_at timestamptz,
               end_at timestamptz, grace_minutes int, pending_count int,
               finalized_at timestamptz, results_updated_at timestamptz)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
begin
  if not (is_member() or is_admin()) then
    raise exception 'forbidden: Login required.' using errcode = '42501';
  end if;
  return query
    select c.id, c.name, contest_effective_status(c.id), c.start_at, c.end_at, c.grace_minutes,
           (select count(*)::int from submissions s where s.contest_id = c.id and s.status = 'pending'),
           c.finalized_at, c.results_updated_at
    from contests c where c.id = current_contest_id();
end $$;

-- ---------------------------------------------------------------------------------------------
-- Member
-- ---------------------------------------------------------------------------------------------
create function create_submission_draft(
  p_category_id uuid, p_reference text, p_note text, p_file_ext text, p_resubmission_of uuid default null)
returns table (submission_id uuid, proof_path text)
language plpgsql security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare
  v_uid uuid := auth.uid();
  v_contest uuid := current_contest_id();
  v_norm text := normalize_reference(p_reference);
  v_ext text := lower(coalesce(p_file_ext, ''));
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_id uuid := gen_random_uuid();
  v_attempt int := 1;
  v_block text;
  v_path text;
begin
  if not is_member() then
    raise exception 'not_member: Only active members can submit.' using errcode = '42501';
  end if;
  if contest_effective_status(v_contest) <> 'open' then
    raise exception 'submissions_closed: Submissions are not open right now.';
  end if;
  if not exists (select 1 from categories c where c.id = p_category_id and c.contest_id = v_contest and c.active) then
    raise exception 'bad_category: Choose a valid category.';
  end if;
  if v_norm = '' then raise exception 'reference_required: Reference is required.'; end if;
  if char_length(btrim(p_reference)) > 200 then raise exception 'reference_too_long: Reference is too long.'; end if;
  if v_note is not null and char_length(v_note) > 280 then
    raise exception 'note_too_long: Note can be at most 280 characters.';
  end if;
  if v_ext not in ('jpg', 'jpeg', 'png', 'webp') then
    raise exception 'bad_file_type: Upload a JPG, PNG or WebP screenshot.';
  end if;
  if (select count(*) from submissions s
      where s.member_id = v_uid and s.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'rate_limited: Too many attempts. Try again later.';
  end if;

  if p_resubmission_of is not null then
    v_block := _resubmission_block(p_resubmission_of, v_uid);
    if v_block is not null then
      raise exception '%: %', v_block, case v_block
        when 'resubmission_limit' then 'This was already resubmitted once. Ask an admin for an override.'
        when 'resubmission_exists' then 'A resubmission already exists for this item.'
        else 'This submission cannot be resubmitted.' end;
    end if;
    if not exists (select 1 from submissions p where p.id = p_resubmission_of and p.category_id = p_category_id) then
      raise exception 'category_mismatch: A resubmission must use the same category.';
    end if;
    select p.attempt + 1 into v_attempt from submissions p where p.id = p_resubmission_of;
  elsif exists (select 1 from submissions s
                where s.member_id = v_uid and s.category_id = p_category_id
                  and s.reference_normalized = v_norm and s.status in ('rejected', 'reversed')) then
    -- Otherwise a rejected item could be re-entered as "new" and dodge the resubmission cap.
    raise exception 'already_reviewed_reference: You already submitted this and it was reviewed. Use Resubmit on the original if it is allowed.';
  end if;

  if exists (select 1 from submissions s
             where s.contest_id = v_contest and s.category_id = p_category_id
               and s.reference_normalized = v_norm and s.status in ('pending', 'approved')) then
    raise exception 'duplicate_reference: This reference has already been submitted.';
  end if;

  v_path := v_contest || '/' || v_uid || '/' || v_id || '.' || case v_ext when 'jpeg' then 'jpg' else v_ext end;
  perform _audit_ctx(null, null);
  insert into submissions (id, contest_id, member_id, category_id, reference, reference_normalized,
                           note, proof_path, status, attempt, resubmission_of)
  values (v_id, v_contest, v_uid, p_category_id, p_reference, v_norm, v_note, v_path, 'draft',
          v_attempt, p_resubmission_of);
  return query select v_id, v_path;
end $$;

-- Called by the confirm-submission Edge Function (service role only) after it has verified the file
-- and hashed it. Impersonates the member so the audit row carries the right actor.
create function confirm_submission_draft(p_member uuid, p_id uuid, p_hash text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_sub submissions;
  v_c contests;
  v_status contest_status;
  v_flags text[] := '{}';
  v_constraint text;
begin
  perform set_config('request.jwt.claim.sub', p_member::text, true);
  perform set_config('request.jwt.claims', jsonb_build_object('sub', p_member, 'role', 'authenticated')::text, true);
  perform _audit_ctx(null, null);

  select * into v_sub from submissions where id = p_id and member_id = p_member and status = 'draft' for update;
  if not found then raise exception 'draft_not_found: Draft not found or already confirmed.'; end if;
  if not exists (select 1 from members m where m.id = p_member and m.active and m.contest_id = v_sub.contest_id) then
    raise exception 'not_member: Only active members can submit.' using errcode = '42501';
  end if;

  select * into v_c from contests where id = v_sub.contest_id;
  v_status := contest_effective_status(v_c.id);
  if not (v_status = 'open'
          or (v_status = 'closed' and v_sub.created_at < v_c.end_at
              and now() <= v_c.end_at + make_interval(mins => v_c.grace_minutes))) then
    raise exception 'submissions_closed: Submissions are closed.';
  end if;

  if v_sub.resubmission_of is not null and not exists (
       select 1 from submissions p where p.id = v_sub.resubmission_of and p.status in ('rejected', 'reversed')) then
    raise exception 'parent_changed: The original submission changed; start again.';
  end if;

  if p_hash is not null and exists (
       select 1 from submissions s
       where s.contest_id = v_sub.contest_id and s.proof_hash = p_hash and s.id <> p_id and s.status <> 'withdrawn') then
    v_flags := array['reused_proof'];
  end if;

  begin
    update submissions
       set status = 'pending', proof_hash = p_hash, submitted_at = now(), flags = v_flags
     where id = p_id;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    delete from submissions where id = p_id;
    return jsonb_build_object('ok', false,
      'error', case v_constraint when 'submissions_resubmission_uq' then 'resubmission_exists'
                                 else 'duplicate_reference' end);
  end;
  return jsonb_build_object('ok', true, 'flags', to_jsonb(v_flags));
end $$;

create function withdraw_submission(p_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_sub submissions;
  v_c contests;
  v_status contest_status;
  v_n int;
begin
  if not is_member() then raise exception 'forbidden: Members only.' using errcode = '42501'; end if;
  select * into v_sub from submissions where id = p_id and member_id = auth.uid();
  if not found then raise exception 'not_found: Submission not found.'; end if;
  select * into v_c from contests where id = v_sub.contest_id;
  v_status := contest_effective_status(v_c.id);
  if not (v_status = 'open' or (v_status = 'closed' and now() <= v_c.end_at + make_interval(mins => v_c.grace_minutes))) then
    raise exception 'submissions_closed: Withdrawals are closed.';
  end if;
  perform _audit_ctx(null, null);
  update submissions set status = 'withdrawn', claimed_by = null, claimed_until = null
   where id = p_id and member_id = auth.uid() and status = 'pending';
  get diagnostics v_n = row_count;
  if v_n = 0 then
    raise exception 'not_pending: Only pending submissions can be withdrawn (it may have just been reviewed).';
  end if;
end $$;

create function my_resubmission_allowance(p_id uuid) returns table (allowed boolean, reason text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_block text;
begin
  if not is_member() then raise exception 'forbidden: Members only.' using errcode = '42501'; end if;
  if contest_effective_status(current_contest_id()) <> 'open' then
    return query select false, 'submissions_closed'::text; return;
  end if;
  v_block := _resubmission_block(p_id, auth.uid());
  return query select (v_block is null), v_block;
end $$;

create function my_submissions()
returns table (id uuid, category_id uuid, category_name text, category_points int, reference text,
               note text, status submission_status, attempt int, resubmission_of uuid,
               points_awarded int, reject_reason_code text, reject_reason_text text,
               proof_path text, created_at timestamptz, submitted_at timestamptz,
               reviewed_at timestamptz, can_resubmit boolean, resubmit_block text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
#variable_conflict use_column
declare v_open boolean;
begin
  if not is_member() then raise exception 'forbidden: Members only.' using errcode = '42501'; end if;
  v_open := contest_effective_status(current_contest_id()) = 'open';
  return query
    select s.id, s.category_id, c.name, c.points, s.reference, s.note, s.status, s.attempt,
           s.resubmission_of, s.points_awarded, s.reject_reason_code, s.reject_reason_text,
           s.proof_path, s.created_at, s.submitted_at, s.reviewed_at,
           (s.status in ('rejected', 'reversed') and v_open and _resubmission_block(s.id, s.member_id) is null),
           case when s.status in ('rejected', 'reversed')
                then case when not v_open then 'submissions_closed' else _resubmission_block(s.id, s.member_id) end end
    from submissions s join categories c on c.id = s.category_id
    where s.member_id = auth.uid() and s.status <> 'draft'
    order by coalesce(s.submitted_at, s.created_at) desc;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Admin
-- ---------------------------------------------------------------------------------------------
create function claim_submission(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_row submissions;
begin
  perform _require_admin();
  perform _audit_ctx(null, null);
  update submissions
     set claimed_by = auth.uid(), claimed_until = now() + interval '5 minutes'
   where id = p_id and status = 'pending'
     and (claimed_by is null or claimed_until is null or claimed_until < now() or claimed_by = auth.uid())
  returning * into v_row;
  if not found then
    select * into v_row from submissions where id = p_id;
    if not found then raise exception 'not_found: Submission not found.'; end if;
    if v_row.status <> 'pending' then raise exception 'already_reviewed: This submission was already reviewed.'; end if;
  end if;
  return jsonb_build_object('mine', v_row.claimed_by = auth.uid(),
                            'claimed_by', v_row.claimed_by, 'claimed_until', v_row.claimed_until);
end $$;

create function approve_submission(p_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_n int;
begin
  perform _require_admin();
  perform _audit_ctx(null, null);
  update submissions s
     set status = 'approved', points_awarded = c.points, reviewed_by = auth.uid(), reviewed_at = now(),
         claimed_by = null, claimed_until = null
    from categories c
   where s.id = p_id and s.status = 'pending' and c.id = s.category_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    if not exists (select 1 from submissions where id = p_id) then
      raise exception 'not_found: Submission not found.';
    end if;
    raise exception 'already_reviewed: This submission was already reviewed.';
  end if;
end $$;

create function reject_submission(p_id uuid, p_reason_code text, p_reason_text text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_n int;
  v_text text := nullif(btrim(coalesce(p_reason_text, '')), '');
begin
  perform _require_admin();
  if p_reason_code is null or p_reason_code not in
     ('unclear_screenshot', 'wrong_category', 'incomplete', 'duplicate', 'staged_self_generated', 'other') then
    raise exception 'reason_required: Choose a rejection reason.';
  end if;
  if p_reason_code = 'other' and v_text is null then
    raise exception 'reason_required: Describe the reason when choosing "other".';
  end if;
  if v_text is not null and char_length(v_text) > 500 then
    raise exception 'reason_too_long: Reason text is too long.';
  end if;
  perform _audit_ctx(null, p_reason_code || coalesce(': ' || v_text, ''));
  update submissions
     set status = 'rejected', reject_reason_code = p_reason_code, reject_reason_text = v_text,
         reviewed_by = auth.uid(), reviewed_at = now(), claimed_by = null, claimed_until = null
   where id = p_id and status = 'pending';
  get diagnostics v_n = row_count;
  if v_n = 0 then
    if not exists (select 1 from submissions where id = p_id) then
      raise exception 'not_found: Submission not found.';
    end if;
    raise exception 'already_reviewed: This submission was already reviewed.';
  end if;
end $$;

-- approved -> reversed. points_awarded stays for the record but is excluded from totals.
create function reverse_submission(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_n int;
  v_reason text;
begin
  perform _require_admin();
  v_reason := _require_reason(p_reason);
  perform _audit_ctx(null, v_reason);
  update submissions
     set status = 'reversed', reject_reason_code = 'reversed', reject_reason_text = v_reason,
         reviewed_by = auth.uid(), reviewed_at = now()
   where id = p_id and status = 'approved';
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'not_approved: Only approved submissions can be reversed.'; end if;
end $$;

-- rejected -> approved (a correction of an admin mistake)
create function correct_rejection(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_n int;
  v_reason text;
begin
  perform _require_admin();
  v_reason := _require_reason(p_reason);
  if exists (select 1 from submissions c
             where c.resubmission_of = p_id and c.status in ('pending', 'approved')) then
    raise exception 'has_live_resubmission: A resubmission is already pending or approved for this item.';
  end if;
  perform _audit_ctx('submission.rejection_corrected', v_reason);
  begin
    update submissions s
       set status = 'approved', points_awarded = c.points, reject_reason_code = null, reject_reason_text = null,
           reviewed_by = auth.uid(), reviewed_at = now()
      from categories c
     where s.id = p_id and s.status = 'rejected' and c.id = s.category_id;
    get diagnostics v_n = row_count;
  exception when unique_violation then
    raise exception 'duplicate_reference: Another pending or approved submission already uses this reference.';
  end;
  if v_n = 0 then raise exception 'not_rejected: Only rejected submissions can be corrected.'; end if;
end $$;

-- Allow one more attempt after a final (2nd) rejection, or after a reversed attempt >= 2.
create function grant_override(p_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_n int;
  v_reason text;
  v_attempt int;
begin
  perform _require_admin();
  v_reason := _require_reason(p_reason);
  select attempt into v_attempt from submissions where id = p_id;
  if v_attempt is null then raise exception 'not_found: Submission not found.'; end if;
  if v_attempt < 2 then raise exception 'override_not_needed: The first rejection already allows a resubmission.'; end if;
  perform _audit_ctx('submission.override_granted', v_reason);
  update submissions set override_granted = true
   where id = p_id and status in ('rejected', 'reversed') and not override_granted;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'override_invalid: Override only applies to a rejected or reversed submission.'; end if;
end $$;

create function set_member_active(p_member uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_n int;
begin
  perform _require_admin();
  perform _audit_ctx(case when p_active then 'member.reactivated' else 'member.deactivated' end, null);
  update members set active = p_active where id = p_member and contest_id = current_contest_id();
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'not_found: Member not found.'; end if;
end $$;

create function upsert_category(
  p_id uuid, p_name text, p_points int, p_reference_label text, p_reference_hint text, p_sort_order int)
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_id uuid := p_id;
begin
  perform _require_admin();
  perform _audit_ctx(null, null);
  if v_id is null then
    insert into categories (contest_id, name, points, reference_label, reference_hint, sort_order)
    values (current_contest_id(), btrim(p_name), p_points, btrim(p_reference_label),
            coalesce(btrim(p_reference_hint), ''), coalesce(p_sort_order, 0))
    returning id into v_id;
  else
    update categories
       set name = btrim(p_name), points = p_points, reference_label = btrim(p_reference_label),
           reference_hint = coalesce(btrim(p_reference_hint), ''), sort_order = coalesce(p_sort_order, sort_order)
     where id = v_id and contest_id = current_contest_id();
    if not found then raise exception 'not_found: Category not found.'; end if;
  end if;
  return v_id;
end $$;

create function set_category_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform _require_admin();
  perform _audit_ctx(null, null);
  update categories set active = p_active where id = p_id and contest_id = current_contest_id();
  if not found then raise exception 'not_found: Category not found.'; end if;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Owner
-- ---------------------------------------------------------------------------------------------
create function update_contest_setup(p_name text, p_start timestamptz, p_end timestamptz, p_grace int) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_id uuid := current_contest_id();
begin
  perform _require_owner();
  if contest_effective_status(v_id) <> 'setup' then
    raise exception 'not_setup: Name and dates can only be edited before the contest starts. Use extend deadline instead.';
  end if;
  perform _audit_ctx('contest.setup_updated', null);
  update contests set name = btrim(p_name), start_at = p_start, end_at = p_end, grace_minutes = p_grace
   where id = v_id;
end $$;

create function set_points_unlocked(p_unlocked boolean, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  perform _audit_ctx(case when p_unlocked then 'contest.points_unlocked' else 'contest.points_locked' end, v_reason);
  update contests set points_unlocked = p_unlocked where id = current_contest_id();
end $$;

create function extend_deadline(p_new_end timestamptz, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  if contest_effective_status(v_id) in ('final', 'archived') then
    raise exception 'contest_frozen: Reopen the contest before extending the deadline.';
  end if;
  if p_new_end <= (select end_at from contests where id = v_id) then
    raise exception 'deadline_shorten: The new deadline must be later than the current one.';
  end if;
  perform _audit_ctx('contest.deadline_extended', v_reason);
  update contests set end_at = p_new_end where id = v_id;
end $$;

create function publish_final(p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_c contests;
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  select * into v_c from contests where id = v_id for update;
  if contest_effective_status(v_id) <> 'closed' then
    raise exception 'not_closed: The contest must be closed before publishing final results.';
  end if;
  if now() <= v_c.end_at + make_interval(mins => v_c.grace_minutes) then
    raise exception 'grace_open: Wait until the grace period after the deadline has ended.';
  end if;
  if exists (select 1 from submissions where contest_id = v_id and status = 'pending') then
    raise exception 'pending_remaining: Review all pending submissions first.';
  end if;
  perform _audit_ctx('contest.published', v_reason);
  update contests
     set manual_status = 'final', finalized_at = now(),
         results_updated_at = case when finalized_at is not null then now() end
   where id = v_id;
end $$;

create function reopen_contest(p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_reason text;
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  if (select manual_status from contests where id = v_id) <> 'final' then
    raise exception 'not_final: Only a final contest can be reopened.';
  end if;
  perform _audit_ctx('contest.reopened', v_reason);
  update contests set manual_status = 'setup' where id = v_id;
end $$;

create function owner_mark_exported() returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_id uuid := current_contest_id();
begin
  perform _require_owner();
  if contest_effective_status(v_id) <> 'final' then
    raise exception 'not_final: Export final results after publishing them.';
  end if;
  perform _audit_ctx('contest.exported', null);
  update contests set exported_at = now() where id = v_id;
end $$;

-- Test environments may set app.archive_min_days (e.g. 0). Production leaves it unset => 30.
create function archive_contest(p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid := current_contest_id();
  v_c contests;
  v_reason text;
  v_days int := coalesce(nullif(current_setting('app.archive_min_days', true), '')::int, 30);
begin
  perform _require_owner();
  v_reason := _require_reason(p_reason);
  select * into v_c from contests where id = v_id for update;
  if v_c.manual_status <> 'final' then
    raise exception 'not_final: Only a final contest can be archived.';
  end if;
  if now() <= v_c.finalized_at + make_interval(days => v_days) then
    raise exception 'too_early: Archiving is allowed % days after results were published.', v_days;
  end if;
  if v_c.exported_at is null or v_c.exported_at < v_c.finalized_at then
    raise exception 'not_exported: Export the final results before archiving.';
  end if;
  perform _audit_ctx('contest.archived', v_reason);
  update contests set manual_status = 'archived' where id = v_id;
end $$;

-- Called with the owner's JWT by the admin-manage Edge Function, after it created the auth user.
create function owner_add_admin(p_user uuid, p_email citext, p_role admin_role) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform _require_owner();
  perform _audit_ctx('admin.added', null);
  insert into admins (id, email, role) values (p_user, p_email, p_role);
end $$;

create function owner_set_admin_active(p_id uuid, p_active boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform _require_owner();
  if not exists (select 1 from admins where id = p_id) then raise exception 'not_found: Admin not found.'; end if;
  if not p_active then
    -- Not removing yourself also guarantees at least one active owner always remains.
    if p_id = auth.uid() then raise exception 'self_remove: You cannot remove yourself.'; end if;
  end if;
  perform _audit_ctx(case when p_active then 'admin.reactivated' else 'admin.removed' end, null);
  update admins set active = p_active where id = p_id;
end $$;

-- ---------------------------------------------------------------------------------------------
-- Service-only helpers (Apps Script / Edge Functions / Auth hook)
-- ---------------------------------------------------------------------------------------------
-- Deleting auth.sessions also removes the session's refresh tokens (FK cascade in GoTrue's schema).
create function revoke_user_sessions(p_user uuid) returns void
language sql security definer set search_path = public, pg_temp as $$
  delete from auth.sessions where user_id = p_user
$$;

create function auth_user_id_by_email(p_email text) returns uuid
language sql stable security definer set search_path = public, pg_temp as $$
  select id from auth.users where lower(email) = lower(btrim(p_email))
$$;

-- Returns true when the request is within limits (3/email/hour, 20/ip/hour). Always records it.
create function rate_limit_key_request(p_email citext, p_ip text) returns boolean
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_by_email int;
  v_by_ip int;
begin
  select count(*) into v_by_email from key_requests
   where email = p_email and requested_at > now() - interval '1 hour';
  select count(*) into v_by_ip from key_requests
   where p_ip is not null and ip = p_ip and requested_at > now() - interval '1 hour';
  insert into key_requests (email, ip) values (p_email, p_ip);
  delete from key_requests where requested_at < now() - interval '2 days';
  return v_by_email < 3 and v_by_ip < 20;
end $$;

-- Optional: Supabase Auth "password verification attempt" hook (Teams/Enterprise plans only).
-- Locks a user for as long as 5+ failed attempts sit inside the last 15 minutes.
create function hook_password_verification_attempt(event jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_user uuid := (event ->> 'user_id')::uuid;
  v_valid boolean := coalesce((event ->> 'valid')::boolean, false);
begin
  delete from login_attempts where attempted_at < now() - interval '1 day';
  if (select count(*) from login_attempts
       where user_id = v_user and attempted_at > now() - interval '15 minutes') >= 5 then
    return jsonb_build_object('decision', 'reject', 'message', 'Email or key is incorrect.');
  end if;
  if v_valid then
    delete from login_attempts where user_id = v_user;
  else
    insert into login_attempts (user_id) values (v_user);
  end if;
  return jsonb_build_object('decision', 'continue');
end $$;

